# === Ревизия, партия rev10 — новая архитектура (10 августа): поиск по
# каждой карточке делает отдельный саб-агент (Task) без потолка на число
# запросов, а не сам поток в своей истории; здесь только обогащение по
# готовым дайджестам.
#
#   g4b275e25 («Киевская площадь»/«Времена года») — КРИТИЧЕСКАЯ НАХОДКА,
#   ПРАВКА НЕ СДЕЛАНА: все три уже привязанных источника карточки (Forbes,
#   Ведомости, РИА Недвижимость) датируют саму сделку «Киевская площадь»
#   купила у «Кэпитал менеджмент»» 11 АПРЕЛЯ 2025 ГОДА, а не 1 декабря
#   2024-го, как стоит в `date`. Карточка, похоже, склеила ДВЕ разные
#   сделки: (а) RD Property Holdings → «Кэпитал менеджмент», закрыта
#   20.12.2024 (даёт декабрьскую дату) и (б) «Кэпитал менеджмент» →
#   «Киевская площадь», закрыта 11.04.2025 (даёт верных продавца и
#   покупателя). review.py не умеет переносить сделку в другой год —
#   нужен отдельный одноразовый скрипт (перенос в 2025 год или разбивка на
#   две карточки), вне мандата этого потока. НЕ трогаю остальные поля
#   карточки, чтобы не наслаивать новые факты поверх спутанной даты.
#   deep_researched проставлен — поиск сделан исчерпывающе, находка именно
#   в этом и состоит.
#
#   law.adv НЕ РЕДАКТИРОВАЛСЯ ни для одной карточки этой партии, хотя
#   консультанты нашлись для нескольких (baltika — Baker McKenzie и
#   Melling, Voitishkin & Partners за Carlsberg; g995f83cf — уже стоят
#   Orion и Никольская Консалтинг, нашлись только имена юристов внутри
#   команд). Причина структурная: `law.adv` — список списков, а
#   `review.py` для не-специальных полей сравнивает ПЛОСКИЙ текст ВСЕГО
#   значения с цитатой (`flat(new) in flat(quote)`), а естественная фраза
#   источника не совпадает по порядку слов со структурированной записью
#   «роль | имя | примечание» — ни один из ~3000 правок в базе не
#   редактирует `law.adv` через `review.py` (проверено `grep` по всем
#   файлам `fixes/*.py`). Это не находка ЭТОЙ партии, а факт устройства
#   инструмента — фиксирую его явно, чтобы не переоткрывать за токены.
#
#   cd9abfbfd (ВТБ/«Аврора Инвест») — нашёл предысторию (сделка 2023 года
#   Лисин → «Аврора Инвест», и переход ПГК под управление ВТБ в 2024-м из-
#   за залога) в двух статьях Ъ, не входивших в src.
#   baltika — второй источник для уже заполненного eco.target_fin даёт
#   точные цифры (выручка/прибыль 2022 года) вместо описательного текста.
#   g4feb42fc (Сайберус/F.A.C.C.T.) — были только два телеграм-канала,
#   нашлись настоящие статьи (Ъ, Ведомости) с структурой владения, финан-
#   сами цели и именными оценками аналитиков вместо анонимной «оценки
#   аналитиков».
#   gf217e953 (Balchug Capital/«Радуга») — law.appr был пуст; армянское
#   СМИ (сам покупатель армянского происхождения) прямо называет одобрение
#   ФАС, по-английски — дословность не требует русского текста, только
#   цитату из РЕАЛЬНО скачанного источника.
#   g995f83cf (Ренкап/Онэксим) — law.appr был пуст, при этом источник (тот
#   же, что уже дал eco.share) прямо говорит о полученных согласованиях;
#   добавлены двухлетний план сделки и масштаб бизнеса цели.

