    #     раскрыта (50 млрд ₽ — это оценка ВСЕГО портфеля недвижимости из
    #     презентации, а не цена сделки), в сделку входит ещё и Global Foods,
    #     названы бенефициар покупателя (Василий Цветков), гендиректор
    #     (Михаил Галуев), учредитель группы «Ароса» (Рустем Миргалимов),
    #     финансы предмета и покупателя, согласование антимонопольной и
    #     правительственной комиссии по контролю за иностранными инвестициями.
    #   gaa603e6d (НОВО/IranianEurasia) — саб-агент нашёл расхождение даты:
    #     все независимые источники (ТАСС, Агроинвестор, собственная лента
    #     evo-centre.ru) называют 14–15 ноября 2024, ни один — 19 ноября;
    #     взята дата Агроинвестора (14 ноября, дословно в байлайне). Также
    #     нашёл более полное техническое описание хаба и состав команды
    #     VERBA LEGAL — оба уже лежали в ранее скачанных источниках. ВАЖНО:
    #     саб-агент нашёл ДРУГОЕ соглашение «Центра развития НОВО» от
    #     24.10.2024 с ДРУГИМ иранским партнёром (Atlas Kesht Rivase Aras) и
