    #   gd2196acd (Совкомбанк/Рокет) — саб-агент нашёл, что согласование ЦБ
    #     не требовалось (проект работает на существующей лицензии
    #     Совкомбанка) и полную историю бренда «Рокетбанк» (2012–2021) в уже
    #     скачанном тексте Коммерсанта. Сумма и диапазон перезапуска нигде не
    #     уточняются сверх уже известного. Гипотеза о продавце («с высокой
    #     долей вероятности АО «Киви»») — не перенесена: источник сам
    #     формулирует её как предположение, а не факт.
