    #     контролирующего акционера, залог долей) — не перенесены, они не
    #     про эту карточку.
    #   ge945a8e1 (Росатом/Future Technologies) — саб-агент подтвердил статус
    #     «Не состоялась» прямой цитатой TAdviser (компания сама сообщила,
    #     что сделки не было) и нашёл описание предмета и его финансов на
